#include <iostream>
#include <fstream>
#include <string>
#include <mutex>
#include <thread>
#include <filesystem>
#include <vector>
#include <chrono>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <sys/stat.h>
#include <unistd.h>

namespace fs = std::filesystem;

class SecureFileProcessor {
private:
    std::string storage_dir_;
    std::string staging_dir_;
    std::mutex process_mutex_;
    unsigned char master_key_[32];

    bool derive_file_key(const std::string& filename, unsigned char* out_key) {
        unsigned char salt[16];
        if (RAND_bytes(salt, sizeof(salt)) != 1) return false;
        return PKCS5_PBKDF2_HMAC(filename.c_str(), filename.size(),
                                  salt, sizeof(salt), 100000,
                                  EVP_sha256(), 32, out_key) == 1;
    }

    std::string get_staging_path(const std::string& job_id) {
        return staging_dir_ + "/" + job_id + ".pending";
    }

    std::string get_final_path(const std::string& job_id) {
        return storage_dir_ + "/" + job_id + ".enc";
    }

    bool validate_job_id(const std::string& job_id) {
        if (job_id.empty() || job_id.size() > 64) return false;
        for (char c : job_id) {
            if (!std::isalnum(c) && c != '-' && c != '_') return false;
        }
        return true;
    }

    int encrypt_and_write(const std::vector<unsigned char>& plaintext,
                          const std::string& output_path,
                          const unsigned char* key) {
        unsigned char iv[12];
        if (RAND_bytes(iv, sizeof(iv)) != 1) return -1;

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return -1;

        std::vector<unsigned char> ciphertext(plaintext.size() + 16);
        int len = 0, ciphertext_len = 0;

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key, iv) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
        if (EVP_EncryptUpdate(ctx, ciphertext.data(), &len, plaintext.data(),
                              static_cast<int>(plaintext.size())) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
        ciphertext_len = len;
        if (EVP_EncryptFinal_ex(ctx, ciphertext.data() + len, &len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
        ciphertext_len += len;

        unsigned char tag[16];
        if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return -1;
        }
        EVP_CIPHER_CTX_free(ctx);

        std::ofstream out(output_path, std::ios::binary);
        if (!out) return -1;
        out.write(reinterpret_cast<char*>(iv), sizeof(iv));
        out.write(reinterpret_cast<char*>(tag), sizeof(tag));
        out.write(reinterpret_cast<char*>(ciphertext.data()), ciphertext_len);
        out.close();
        return 0;
    }

public:
    SecureFileProcessor(const std::string& storage, const std::string& staging)
        : storage_dir_(storage), staging_dir_(staging) {
        if (RAND_bytes(master_key_, sizeof(master_key_)) != 1) {
            throw std::runtime_error("Failed to generate master key");
        }
        fs::create_directories(storage_dir_);
        fs::create_directories(staging_dir_);
    }

    int submit_job(const std::string& job_id, const std::vector<unsigned char>& data) {
        if (!validate_job_id(job_id)) return -1;

        std::lock_guard<std::mutex> lock(process_mutex_);

        std::string final_path = get_final_path(job_id);

        // Check if job already exists in final storage
        if (fs::exists(final_path)) return -2;

        // Encrypt directly from memory - no staging file needed
        unsigned char file_key[32];
        if (!derive_file_key(job_id, file_key)) return -7;

        int result = encrypt_and_write(data, final_path, file_key);

        explicit_bzero(file_key, sizeof(file_key));
        return result;
    }

    int process_batch(const std::vector<std::pair<std::string, std::vector<unsigned char>>>& jobs) {
        // Process jobs sequentially - submit_job handles its own locking
        int success_count = 0;
        for (const auto& [job_id, data] : jobs) {
            if (submit_job(job_id, data) == 0) {
                success_count++;
            }
        }
        return success_count;
    }
};

int main(int argc, char* argv[]) {
    if (argc < 2) {
        std::cerr << "Usage: " << argv[0] << " <storage_dir>" << std::endl;
        return 1;
    }

    SecureFileProcessor processor(argv[1], "/tmp");

    // Example: process a file from stdin
    std::string job_id;
    std::cout << "Enter job ID: ";
    std::getline(std::cin, job_id);

    std::vector<unsigned char> data((std::istreambuf_iterator<char>(std::cin)),
                                     std::istreambuf_iterator<char>());

    int result = processor.submit_job(job_id, data);
    if (result == 0) {
        std::cout << "Job " << job_id << " processed successfully." << std::endl;
    } else {
        std::cerr << "Job failed with code: " << result << std::endl;
    }
    return result;
}
